lib_src = '''"""General grid helpers for ARC-style tasks."""
from collections import Counter


def background(g):
    """Return the most common grid value."""
    return Counter(v for row in g for v in row).most_common(1)[0][0]


def cells_of(g, c):
    """Return the set of (i, j) coordinates where grid g equals c."""
    return {(i, j) for i in range(len(g)) for j in range(len(g[0])) if g[i][j] == c}


def row_bands(cells):
    """Split sprite cells into contiguous row bands (two copies separated by empty rows)."""
    rows = sorted({i for i, j in cells})
    bands = []
    cur = [rows[0]]
    for r in rows[1:]:
        if r - cur[-1] > 1:
            bands.append(cur); cur = [r]
        else:
            cur.append(r)
    bands.append(cur)
    return bands


def best_containment_translation(X, Y, H, W):
    """Find (dr, dc) maximizing clipped cells of X translated into Y while fully contained in Y."""
    best = None
    for dr in range(-H, H + 1):
        for dc in range(-W, W + 1):
            T = {(i + dr, j + dc) for (i, j) in X if 0 <= i + dr < H and 0 <= j + dc < W}
            if not T or not T <= Y:
                continue
            if best is None or len(T) > best[0]:
                best = (len(T), dr, dc)
    return best


def paint_translated_extras(g, color=1):
    """Two copies of a sprite: paint (in the base copy's frame) the translated copy's extra cells."""
    H, W = len(g), len(g[0])
    bg = background(g)
    sprite = [v for v in Counter(v for row in g for v in row) if v != bg]
    out = [row[:] for row in g]
    if len(sprite) != 1:
        return None
    P = cells_of(g, sprite[0])
    bands = row_bands(P)
    if len(bands) != 2:
        return None
    A = {(i, j) for (i, j) in P if bands[0][0] <= i <= bands[0][-1]}
    B = {(i, j) for (i, j) in P if bands[1][0] <= i <= bands[1][-1]}
    # base X: translated X is fully contained in Y, which has extras
    best = None
    for X, Y in ((A, B), (B, A)):
        r = best_containment_translation(X, Y, H, W)
        if r and (best is None or r[0] > best[0][0]):
            best = (r, X, Y)
    (score, dr, dc), X, Y = best
    T = {(i + dr, j + dc) for (i, j) in X if 0 <= i + dr < H and 0 <= j + dc < W}
    for (i, j) in Y - T:
        bi, bj = i - dr, j - dc
        if 0 <= bi < H and 0 <= bj < W:
            out[bi][bj] = color
    return out
'''
